// T14 — the Summary card's SECTION HEADINGS: `## Premise` reads as `## Premise (v7) 100%`.
//
// THE REQUIREMENT, verbatim: "The heading should have format: `Premise (v2) 100%` where v2 is the clean
// revision version, and the percentage is how rated by reader."
//
// WHY THE DECORATION IS APPLIED HERE AND NEVER WRITTEN ANYWHERE. The Overview is generated text, and it is
// generated by ONE producer with a byte-exact contract (§4.19: `shared/phrase.ts:composePhraseContent` — one
// `## <title>` per non-empty group, the text under it, a blank line between, no trailing newline). That text is
// not merely displayed: Phrase ②'s Start copies it VERBATIM onto its Seed and the Seed is hashed (§4.20 / D-72,
// `PlotlinesHandoff.tsx`), so a heading that carried a number here would put a number into the copied Seed and
// into the prompt cache key of every downstream run. D-65's boundary (§2's P6 exception, §17.14) is the other
// half of the reason: a Reader's score is display-only and "never recomputed, averaged or re-scaled", so it may
// not become stored content either. Rendering is the only place left, and U-23 (§10.2) already made this card a
// RENDERED document — the decoration is a rendering rule on the text U-23 renders, which is what this module is.
//
// WHY A PURE MODULE AND NOT AN INLINE MAP IN THE PANE. Every other presentation rule the desk prints lives in a
// pure function the pane calls (`story-contract.ts:phraseScorePercent`, `:reviewedGapReason`,
// `:revisionBodyText`), so the rule is testable without React and the pane stays one read. This one is separate
// from `story-contract.ts` only because it is a TEXT transform rather than a payload read — and because another
// worker owns that file.
//
// WHY THE NUMBERS ARRIVE ALREADY NORMALISED. `score` is the number the selectors already print on the
// provenance strip and the rail (`reviewedGroupRows` → `phraseScorePercent`, the ONE rounding/clamping rule),
// and `revision` is the clean `selected_revision` (or, on a chosen book, `chosen.vector` — the pane resolves
// which before calling). This module therefore re-derives NOTHING: it formats the two values it is handed, and
// prints neither when it was handed neither. An absent score prints nothing rather than `0%`, exactly as
// `StoryOutline.tsx:681-696` and the provenance strip already behave — a zero is a judgement and an absence is
// not one (D-65).
//
// THE RULES, in the order the scanner applies them:
//   1. Only an ATX h2 whose trimmed text EQUALS a reviewed row's trimmed title is a heading. Matching is by
//      TITLE, never by position: the producer's catalog order is a fact about one build's catalog, and an
//      Overview whose groups were retitled (or whose order changed) must not have one section's numbers glued
//      onto another section's heading.
//   2. A line inside a fenced code block is code, not a heading, so `## Premise` inside a fence stays literal.
//   3. Only the FIRST occurrence per group is decorated: the producer writes one heading per group, so a second
//      `## Premise` is the Author's prose quoting a heading, and decorating both would claim two sections.
//   4. `(v<n>)` appears only when the clean revision exists, `<pct>%` only when the score exists, and when
//      NEITHER exists the line is returned byte-for-byte unchanged.
//   5. Idempotent by construction: the decorated line's text (`Premise (v7) 100%`) no longer equals any group's
//      title, so feeding the output back in changes nothing.
//   6. Nothing else in the document moves — not a body line's bytes, not a `###` line, not the line endings,
//      not the producer's "no trailing newline".
import { isInvalid } from '@presource/core';

/**
 * ONE group's two display numbers, in exactly the shape the pane's reviewed rows already answer
 * (`SummaryOverviewPane.tsx`'s `reviewedRows`, which is `story-contract.ts:reviewedGroupRows` plus the
 * chosen-book read). Structural rather than imported so this module stays free of the payload types and of the
 * file another worker owns.
 */
export interface SummaryHeadingRow {
    /** The group's display TITLE — the catalog's spelling, which is what the producer wrote after `## `. */
    title: string;
    /** The clean revision the reviewed Overview stands behind; `null`/`undefined` ⇒ print no `(v<n>)`. */
    revision?: number | null;
    /** The percentage the selectors already normalised; `undefined` ⇒ print no `<pct>%`. A real 0 prints. */
    score?: number;
}

/**
 * An ATX level-2 heading opener: up to THREE leading spaces (a fourth makes indented CODE in CommonMark, and
 * code is never a heading), exactly two `#` — so `#`, `###` and `####` lines are not this — and then a space or
 * tab, which is what `##Premise` is not (a heading needs the space, and `##Premise` is one paragraph of text).
 */
const SECTION_HEADING = /^ {0,3}##[ \t]+/;

/** A fenced-code delimiter line: up to three spaces of indent, then three or more ``` or ~~~. */
const CODE_FENCE = /^ {0,3}(`{3,}|~{3,})/;

// TWO markdown forms this rule handles narrowly, and why, so the next agent reads a decision rather than an
// oversight (both are pinned in `summary-heading.test.ts`):
//   - a blockquoted heading (`> ## Premise`) is NOT decorated — the rule the user asked for is "a line that is
//     exactly `## <title>` at line start", and a blockquote marker means the line does not start with the
//     heading. It renders as an undecorated h2 inside the quote, i.e. exactly as it did before this module;
//   - a heading line inside a RAW HTML block (`<div>` / `## Premise` / `</div>`) IS decorated, because markdown
//     swallows those lines as HTML rather than parsing them and this scanner tracks FENCES only. Nothing is
//     mangled by that: with no `rehype-raw` (U-23) the whole block already renders as escaped TEXT, so the
//     Author was reading `## Premise` as characters before, and reads `## Premise (v7) 100%` as characters now.
// Neither form comes from the producer — `composePhraseContent` writes `## <title>` at column 0 and its body as
// plain prose — so both are tolerance for agent prose rather than shipped states.

/**
 * The text appended to ONE heading: ` (v7) 100%`, ` (v7)`, ` 100%`, or `''` when the group has neither number.
 *
 * The separator is a single space in every case, so the absent-revision form is `Premise 100%` rather than
 * `Premise  100%` with a hole in it. `isInvalid` (null/undefined) rather than a truthiness test, because `0` is
 * a valid value for BOTH fields on the edge of the wire: revision 0 is a book that has never installed a
 * revision, and score 0 is a judgement the Reader actually made.
 */
function headingSuffix(row: SummaryHeadingRow): string {
    const parts: string[] = [];

    if (!isInvalid(row.revision)) parts.push(`(v${row.revision})`);
    if (!isInvalid(row.score)) parts.push(`${row.score}%`);

    return parts.length === 0 ? '' : ` ${parts.join(' ')}`;
}

/**
 * The document, cut into lines WITH their endings intact (`eol` is `''` for the final line when the producer
 * ended without one).
 *
 * `split('\n')` would drop a `\r` and rejoin a CRLF payload as LF, which is a byte change to body lines the rule
 * forbids; the producer writes `\n` today, and this keeps a payload that ever stops doing it honest.
 */
function splitLines(text: string): Array<{ text: string; eol: string }> {
    const lines: Array<{ text: string; eol: string }> = [];
    const pattern = /([^\r\n]*)(\r\n|\r|\n)/g;
    let cursor = 0;
    let match = pattern.exec(text);

    while (match !== null) {
        lines.push({ text: match[1], eol: match[2] });
        cursor = pattern.lastIndex;
        match = pattern.exec(text);
    }

    // Whatever sits after the last newline — the producer's no-trailing-newline final line, or `''` when the
    // text genuinely ended with one (then this empty remainder is the trailing newline, kept as it was).
    lines.push({ text: text.slice(cursor), eol: '' });

    return lines;
}

/**
 * The reviewed Overview's section headings, decorated: `## Premise` → `## Premise (v7) 100%`.
 *
 * `text` is the WIRE text — `reviewed.overview` / `chosen.overview` exactly as it arrives — and `rows` is the
 * pane's reviewed rows. Everything that is not a matching heading line comes back byte-identical, the line
 * endings included, so the value this returns is still the same document Phrase ② would copy.
 *
 * A group with a title that matches no heading (unwritten, so the producer skipped it; or retired, so the
 * catalog renamed it) is simply not decorated — the producer skips empty sections, and this module never adds
 * one.
 */
export function decorateSummaryOverview(text: string, rows: readonly SummaryHeadingRow[]): string {
    if (text === '') return text;

    // Title → row, FIRST occurrence wins: catalog titles are distinct, and if a payload ever repeated one, the
    // first row is the one the composition order puts on screen. A blank title can match nothing meaningful
    // (`## ` is not a section), so it is dropped here rather than decorating an empty heading.
    const byTitle = new Map<string, SummaryHeadingRow>();

    for (const row of rows) {
        const title = row.title.trim();

        if (title !== '' && !byTitle.has(title)) byTitle.set(title, row);
    }

    if (byTitle.size === 0) return text;

    const lines = splitLines(text);
    // Rules 1 and 5: a title is spent on its first occurrence, which also makes the decorated line (`Premise
    // (v7) 100%`) unmatchable on a second pass — the scan is its own guard against double-decoration.
    const decorated = new Set<string>();
    // Rule 2, tracked the way GFM closes a fence: the opener's character and length, and a closer has to match
    // both. An UNCLOSED fence swallows the rest of the document, which is exactly what markdown does with it —
    // so a stray ``` in agent prose cannot turn a code sample's `## Premise` into a decorated heading.
    let fence: string | null = null;

    for (const line of lines) {
        const fenceMatch = CODE_FENCE.exec(line.text);

        if (fenceMatch !== null) {
            const marker = fenceMatch[1];

            if (fence === null) fence = marker;
            else if (marker[0] === fence[0] && marker.length >= fence.length) fence = null;

            continue;
        }

        if (fence !== null || !SECTION_HEADING.test(line.text)) continue;

        // The heading's text is everything after the `## ` opener, trimmed of the trailing spaces ATX ignores.
        // Comparison is `===` on trimmed text — exact title equality, so `## Premise II` is not `Premise`.
        const title = line.text.replace(SECTION_HEADING, '').trim();
        const row = byTitle.get(title);

        if (row === undefined || decorated.has(title)) continue;
        decorated.add(title);

        const suffix = headingSuffix(row);

        if (suffix === '') {
            // Rule 4: neither number means NOTHING is written to this line — not even a tidy-up of its spacing,
            // because the byte-for-byte output is what the tests can promise to a text Phrase ② copies.
            continue;
        }

        // The opener and the title keep their own bytes; only the heading line's trailing whitespace is dropped,
        // so `## Premise ` cannot gain `Premise  (v7)`'s double space.
        line.text = `${line.text.trimEnd()}${suffix}`;
    }

    return lines.map((line) => `${line.text}${line.eol}`).join('');
}

export default decorateSummaryOverview;
